      "state": { "fieldMode": "curl F + n dS", "emphasis": "Surface S" }
    },
    {
      "title": "Fade the surface, keep the boundary",
      "narration": "Dim the tube and highlight only the front circular opening C with its orientation arrows. The convoluted surface is nearly impossible to parameterize.",
      "state": { "fieldMode": "curl F + n dS", "emphasis": "Boundary C" }
    },
    {
      "title": "Stokes' trade",
      "narration": "Both shown together: the surface integral of curl F over all of S equals the line integral of F around the single small circle C — the hard object is traded for the easy one.",
      "state": { "fieldMode": "F (vector field)", "emphasis": "Both" }
    }
