<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   world box        → LineSegments(EdgesGeometry(BoxGeometry(6,6,6)))  #5B9BD5
   axes x,y,z       → Line (black) ±3.2 + ConeGeometry arrowheads at + ends
   ticks            → LineSegments every 0.5 unit, black, 0.09 long
   tube S           → TubeGeometry(CatmullRomCurve3, 400, 0.35, 24, open)
                      MeshStandardMaterial #6E7CA3 DoubleSide
   inner wall       → second TubeGeometry r=0.33, BackSide, #55618A
   far mouth rim    → TorusGeometry(0.35,0.030) at curve u=0  (#55618A)
   boundary C rim   → TorusGeometry(0.35,0.038) at curve u=1  (color switches)
   field arrows     → pooled Group(CylinderGeometry shaft + ConeGeometry head)
                      64 on a 4x4x4 grid + 16 on the tube surface, #E8622A
   curl arrows      → same pool re-aimed, #C0392B, length ∝ |0.5z|
   normals n dS     → 16 pooled arrows on tube, #4C8C6B, length 0.35
   orientation of C → 6 small tangential arrows on the C circle, gold
   labels x,y,z,S,C → addLabel
   Math coords (x lower-left, y lower-right, z up) map to world as
   world = (mathY, mathZ, mathX).
──────────────────────────────────────────────────────────────────────────── */

const COL = {
  box: 0x5B9BD5, tube: 0x6E7CA3, inner: 0x55618A,
  field: 0xE8622A, curl: 0xC0392B, normal: 0x4C8C6B, gold: 0xD9A02B
};

const M = (x, y, z) => new THREE.Vector3(y, z, x);          // math → world
const mathOf = (p) => ({ x: p.z, y: p.x, z: p.y });          // world → math

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0x8a90a6, 0.85));
const key = new THREE.DirectionalLight(0xffffff, 0.75);
key.position.set(1.5, 6, 5.5);
scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.25);
fill.position.set(-4, -2, -3);
scene.add(fill);

/* ── wireframe box ──────────────────────────────────────────────────────── */
const boxGroup = new THREE.Group();
boxGroup.add(new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(6, 6, 6)),
  new THREE.LineBasicMaterial({ color: COL.box })
));
scene.add(boxGroup);

/* ── axes + ticks + arrowheads ──────────────────────────────────────────── */
const axesGroup = new THREE.Group();
scene.add(axesGroup);
const blackLine = new THREE.LineBasicMaterial({ color: 0x111111 });
const blackSolid = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6 });

const AX = [
  { dir: M(1, 0, 0), tick: new THREE.Vector3(0, 1, 0) },   // math x  (world +Z)
  { dir: M(0, 1, 0), tick: new THREE.Vector3(0, 1, 0) },   // math y  (world +X)
  { dir: M(0, 0, 1), tick: new THREE.Vector3(1, 0, 0) }    // math z  (world +Y)
];
const tickPts = [];
for (const a of AX) {
  const L = 3.2;
  axesGroup.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      a.dir.clone().multiplyScalar(-L), a.dir.clone().multiplyScalar(L)
    ]), blackLine));
  for (let s = -6; s <= 6; s++) {
    if (s === 0) continue;
    const base = a.dir.clone().multiplyScalar(s * 0.5);
    tickPts.push(base.clone().addScaledVector(a.tick, 0.085));
    tickPts.push(base.clone().addScaledVector(a.tick, -0.085));
  }
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.26, 14), blackSolid);
  head.position.copy(a.dir).multiplyScalar(L + 0.12);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), a.dir.clone().normalize());
  axesGroup.add(head);
}
axesGroup.add(new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints(tickPts), blackLine));

/* ── tube S ─────────────────────────────────────────────────────────────── */
// waypoints in math coords: upper lobe (behind) -> left turn -> lower lobe
// (in front) -> right U-turn -> back to the front-facing opening C at centre.
const MATH_PTS = [
  [-1.958, 1.012, 0.446],   // far open mouth, upper right
  [-1.333, -0.485, 0.317],  // upper lobe, behind the z axis
  [0.719, -1.543, 0.324],   // upper lobe, left end
  [1.718, -0.970, 0.252],   // left turn, coming forward
  [1.635, -0.062, -0.072],  // lower lobe, front left
  [0.530, 0.954, -0.484],   // lower lobe, front centre
  [-0.885, 1.943, -0.758],  // lower lobe, right
  [-1.493, 1.972, -0.679],  // U-turn
  [-1.825, 1.429, -0.504],  // U-turn back
  [-1.014, 0.259, -0.745],  // heading back to centre, behind
  [0.335, 0.546, 0.319]     // boundary circle C, facing the viewer
];
const curve = new THREE.CatmullRomCurve3(
  MATH_PTS.map(p => M(p[0], p[1], p[2])), false, 'catmullrom', 0.5);

const R = 0.35;
const tubeMat = new THREE.MeshStandardMaterial({
  color: COL.tube, roughness: 0.5, metalness: 0.05, side: THREE.DoubleSide
});
const innerMat = new THREE.MeshStandardMaterial({
  color: COL.inner, roughness: 0.7, metalness: 0.0, side: THREE.BackSide
});
const tubeGroup = new THREE.Group();
const tubeMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 400, R, 24, false), tubeMat);
const innerMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 300, R - 0.02, 20, false), innerMat);
tubeGroup.add(tubeMesh, innerMesh);
scene.add(tubeGroup);

registerInteractive(tubeMesh, {
  title: 'Surface S',
  tooltip: 'Surface S — too convoluted to parameterize',
  body: 'S is an oriented tube that winds and doubles back on itself. Computing ∬_S (curl F)·n dS directly would require a parameterization of this whole twisted surface.'
});

// rims at both open ends
function ringAt(u, tubeR, color) {
  const p = curve.getPointAt(u);
  const t = curve.getTangentAt(u).normalize();
  const m = new THREE.Mesh(
    new THREE.TorusGeometry(R, tubeR, 12, 44),
    new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.1 })
  );
  m.position.copy(p);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), t);
  scene.add(m);
  return m;
}
const rimFar = ringAt(0, 0.030, COL.inner);
const rimC = ringAt(1, 0.040, COL.inner);
registerInteractive(rimC, {
  title: 'Boundary curve C',
  tooltip: 'Boundary circle C',
  body: 'C is the single oriented boundary circle of S. Stokes\' theorem replaces the surface integral of curl F over S with the line integral of F around C.'
});

/* ── arrow pool ─────────────────────────────────────────────────────────── */
const shaftGeo = new THREE.CylinderGeometry(0.026, 0.026, 1, 8);
shaftGeo.translate(0, 0.5, 0);
const headGeo = new THREE.ConeGeometry(0.078, 0.17, 12);
headGeo.translate(0, 0.085, 0);
const UPY = new THREE.Vector3(0, 1, 0);

