const blackLine = new THREE.LineBasicMaterial({ color: 0x111111 });
const blackSolid = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6 });

const AX = [
  { dir: M(1, 0, 0), tick: new THREE.Vector3(0, 1, 0) },   // math x  (world +Z)
  { dir: M(0, 1, 0), tick: new THREE.Vector3(0, 1, 0) },   // math y  (world +X)
  { dir: M(0, 0, 1), tick: new THREE.Vector3(1, 0, 0) }    // math z  (world +Y)
];
const tickPts = [];
for (const a of AX) {
  const L = 3.2;
  axesGroup.add(new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([
      a.dir.clone().multiplyScalar(-L), a.dir.clone().multiplyScalar(L)
    ]), blackLine));
  for (let s = -6; s <= 6; s++) {
    if (s === 0) continue;
    const base = a.dir.clone().multiplyScalar(s * 0.5);
    tickPts.push(base.clone().addScaledVector(a.tick, 0.085));
    tickPts.push(base.clone().addScaledVector(a.tick, -0.085));
  }
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.26, 14), blackSolid);
  head.position.copy(a.dir).multiplyScalar(L + 0.12);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), a.dir.clone().normalize());
  axesGroup.add(head);
}
axesGroup.add(new THREE.LineSegments(
  new THREE.BufferGeometry().setFromPoints(tickPts), blackLine));

/* ── tube S ─────────────────────────────────────────────────────────────── */
// waypoints in math coords: upper lobe (behind) -> left turn -> lower lobe
// (in front) -> right U-turn -> back to the front-facing opening C at centre.
const MATH_PTS = [
  [-1.958, 1.012, 0.446],   // far open mouth, upper right
  [-1.333, -0.485, 0.317],  // upper lobe, behind the z axis
  [0.719, -1.543, 0.324],   // upper lobe, left end
  [1.718, -0.970, 0.252],   // left turn, coming forward
  [1.635, -0.062, -0.072],  // lower lobe, front left
  [0.530, 0.954, -0.484],   // lower lobe, front centre
  [-0.885, 1.943, -0.758],  // lower lobe, right
  [-1.493, 1.972, -0.679],  // U-turn
  [-1.825, 1.429, -0.504],  // U-turn back
  [-1.014, 0.259, -0.745],  // heading back to centre, behind
  [0.335, 0.546, 0.319]     // boundary circle C, facing the viewer
];
const curve = new THREE.CatmullRomCurve3(
  MATH_PTS.map(p => M(p[0], p[1], p[2])), false, 'catmullrom', 0.5);

const R = 0.35;
const tubeMat = new THREE.MeshStandardMaterial({
  color: COL.tube, roughness: 0.5, metalness: 0.05, side: THREE.DoubleSide
});
const innerMat = new THREE.MeshStandardMaterial({
  color: COL.inner, roughness: 0.7, metalness: 0.0, side: THREE.BackSide
});
const tubeGroup = new THREE.Group();
const tubeMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 400, R, 24, false), tubeMat);
const innerMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 300, R - 0.02, 20, false), innerMat);
tubeGroup.add(tubeMesh, innerMesh);
scene.add(tubeGroup);

registerInteractive(tubeMesh, {
  title: 'Surface S',
  tooltip: 'Surface S — too convoluted to parameterize',
  body: 'S is an oriented tube that winds and doubles back on itself. Computing ∬_S (curl F)·n dS directly would require a parameterization of this whole twisted surface.'
});

// rims at both open ends
function ringAt(u, tubeR, color) {
  const p = curve.getPointAt(u);
  const t = curve.getTangentAt(u).normalize();
  const m = new THREE.Mesh(
    new THREE.TorusGeometry(R, tubeR, 12, 44),
    new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.1 })
  );
  m.position.copy(p);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), t);
  scene.add(m);
  return m;
}
const rimFar = ringAt(0, 0.030, COL.inner);
const rimC = ringAt(1, 0.040, COL.inner);
registerInteractive(rimC, {
  title: 'Boundary curve C',
  tooltip: 'Boundary circle C',
  body: 'C is the single oriented boundary circle of S. Stokes\' theorem replaces the surface integral of curl F over S with the line integral of F around C.'
});

/* ── arrow pool ─────────────────────────────────────────────────────────── */
const shaftGeo = new THREE.CylinderGeometry(0.026, 0.026, 1, 8);
shaftGeo.translate(0, 0.5, 0);
const headGeo = new THREE.ConeGeometry(0.078, 0.17, 12);
headGeo.translate(0, 0.085, 0);
const UPY = new THREE.Vector3(0, 1, 0);

const matField = new THREE.MeshStandardMaterial({ color: COL.field, roughness: 0.65 });
const matCurl = new THREE.MeshStandardMaterial({ color: COL.curl, roughness: 0.65 });
const matNorm = new THREE.MeshStandardMaterial({ color: COL.normal, roughness: 0.65 });
const matGold = new THREE.MeshStandardMaterial({ color: COL.gold, roughness: 0.4, metalness: 0.2 });

function makeArrow(mat, parent) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(shaftGeo, mat);
  const head = new THREE.Mesh(headGeo, mat);
  g.add(shaft, head);
  g.userData = { shaft, head };
  parent.add(g);
  return g;
}
function setArrow(g, centre, dir, len, mat) {
  if (!(len > 0.002) || dir.lengthSq() < 1e-10) { g.visible = false; return; }
  const dnorm = dir.clone().normalize();
  g.visible = true;
  g.position.copy(centre).addScaledVector(dnorm, -len / 2);
  g.quaternion.setFromUnitVectors(UPY, dnorm);
  const hl = Math.min(0.17, len * 0.5);
  g.userData.shaft.scale.set(1, Math.max(0.01, len - hl), 1);
  g.userData.head.position.set(0, len - hl, 0);
  const hs = Math.min(1.05, Math.max(0.6, len / 0.45));
  g.userData.head.scale.setScalar(hs);
  if (mat) { g.userData.shaft.material = mat; g.userData.head.material = mat; }
}

/* field + curl definitions (math coords) */
function Fworld(p) {
  const m = mathOf(p);
  const fx = 1 + 0.25 * m.z * m.z, fy = 1, fz = 0.4 + 0.4 * m.z;
  return M(fx, fy, fz);                     // same map as positions
}
function curlWorld(p) {
  const m = mathOf(p);
  return M(0, 0.5 * m.z, 0);
}

/* grid samples */
const gridGroup = new THREE.Group(); scene.add(gridGroup);
const gridArrows = [];
const GV = [-2.5, -0.8333, 0.8333, 2.5];
for (const gx of GV) for (const gy of GV) for (const gz of GV) {
  const p = M(gx, gy, gz);
  const a = makeArrow(matField, gridGroup);
  gridArrows.push({ g: a, p });
}

/* surface samples (arrows lying across the tube, plus normals) */
const surfGroup = new THREE.Group(); scene.add(surfGroup);
const normGroup = new THREE.Group(); scene.add(normGroup);
const surfArrows = [], normArrows = [];
const viewDir = new THREE.Vector3(1, 1, 1).normalize();
for (let i = 0; i < 16; i++) {
  const u = 0.03 + 0.94 * (i / 15);
  const pos = curve.getPointAt(u);
  const tan = curve.getTangentAt(u).normalize();
  let n1 = new THREE.Vector3().crossVectors(tan, UPY);
  if (n1.lengthSq() < 1e-6) n1 = new THREE.Vector3().crossVectors(tan, new THREE.Vector3(1, 0, 0));
  n1.normalize();
  const n2 = new THREE.Vector3().crossVectors(tan, n1).normalize();
  let best = null, bestDot = -Infinity;
  for (let k = 0; k < 24; k++) {
    const th = (k / 24) * Math.PI * 2;
    const rad = n1.clone().multiplyScalar(Math.cos(th)).addScaledVector(n2, Math.sin(th));
    const dd = rad.dot(viewDir);
    if (dd > bestDot) { bestDot = dd; best = rad; }
  }
  const sp = pos.clone().addScaledVector(best, R + 0.02);
  surfArrows.push({ g: makeArrow(matField, surfGroup), p: sp });
  const na = makeArrow(matNorm, normGroup);
  setArrow(na, sp.clone().addScaledVector(best, 0.16), best.clone(), 0.35, matNorm);
  normArrows.push({ g: na, p: sp, n: best.clone() });
}

/* orientation arrows around C */
const orientGroup = new THREE.Group(); scene.add(orientGroup);
{
  const cEnd = curve.getPointAt(1);
  const cTan = curve.getTangentAt(1).normalize();
  let n1 = new THREE.Vector3().crossVectors(cTan, UPY);
  if (n1.lengthSq() < 1e-6) n1 = new THREE.Vector3().crossVectors(cTan, new THREE.Vector3(1, 0, 0));
  n1.normalize();
  const n2 = new THREE.Vector3().crossVectors(cTan, n1).normalize();
  for (let i = 0; i < 6; i++) {
    const th = (i / 6) * Math.PI * 2;
    const rad = n1.clone().multiplyScalar(Math.cos(th)).addScaledVector(n2, Math.sin(th));
    const p = cEnd.clone().addScaledVector(rad, R);
    const tdir = new THREE.Vector3().crossVectors(cTan, rad).normalize();
    const a = makeArrow(matGold, orientGroup);
    setArrow(a, p, tdir, 0.26, matGold);
  }
}
orientGroup.visible = false;

/* ── state & updates ───────────────────────────────────────────────────── */
let mode = 'F';            // 'F' | 'curl'
let emphasis = 'S';        // 'S' | 'C' | 'B'
let tubeTargetOpacity = 1;

function updateArrows() {
  const all = gridArrows.concat(surfArrows);
  for (const e of all) {
    if (mode === 'F') {
      setArrow(e.g, e.p, Fworld(e.p), 0.45, matField);
    } else {
      const m = mathOf(e.p);
      const mag = Math.abs(0.5 * m.z);
      if (mag < 0.09) { e.g.visible = false; continue; }
      setArrow(e.g, e.p, curlWorld(e.p), Math.min(0.5, Math.max(0.15, mag)), matCurl);
    }
  }
  normGroup.visible = (mode === 'curl');
  gridGroup.visible = document.getElementById('cbGrid').checked;
  surfGroup.visible = document.getElementById('cbSurf').checked;
  normGroup.visible = normGroup.visible && document.getElementById('cbSurf').checked;
}

function updateEmphasis() {
  if (emphasis === 'S') { tubeTargetOpacity = 1.0; rimC.material.color.setHex(COL.inner); orientGroup.visible = false; rimC.scale.setScalar(1); }
  else if (emphasis === 'C') { tubeTargetOpacity = 0.15; rimC.material.color.setHex(COL.gold); orientGroup.visible = true; rimC.scale.setScalar(1.12); }
  else { tubeTargetOpacity = 0.55; rimC.material.color.setHex(COL.gold); orientGroup.visible = true; rimC.scale.setScalar(1.12); }
}

function applyOpacity(v) {
  for (const m of [tubeMat, innerMat]) {
    m.opacity = v;
    m.transparent = v < 0.995;
    m.depthWrite = v > 0.995;
    m.needsUpdate = true;
  }
}

/* buttons */
const bF = document.getElementById('btnModeF'), bC = document.getElementById('btnModeCurl');
const eS = document.getElementById('btnEmS'), eC = document.getElementById('btnEmC'), eB = document.getElementById('btnEmB');
const modeNote = document.getElementById('modeNote');

function syncUI() {
  bF.classList.toggle('active', mode === 'F');
  bC.classList.toggle('active', mode === 'curl');
  eS.classList.toggle('active', emphasis === 'S');
  eC.classList.toggle('active', emphasis === 'C');
  eB.classList.toggle('active', emphasis === 'B');
  modeNote.innerHTML = mode === 'F'
    ? '<b>F</b> = (1 + 0.25z², 1, 0.4 + 0.4z): arrows tilt up and to the right, more steeply high in the box.'
    : '<b>curl F</b> = (0, 0.5z, 0) in red — it vanishes on z = 0 and grows away from it. Green arrows are the outward unit normals <b>n</b> on S; the integrand is curl F · n.';
}
function setMode(m) { mode = m; updateArrows(); syncUI(); }
function setEmph(e) { emphasis = e; updateEmphasis(); syncUI(); }

bF.onclick = () => setMode('F');
bC.onclick = () => setMode('curl');
eS.onclick = () => setEmph('S');
eC.onclick = () => setEmph('C');
eB.onclick = () => setEmph('B');
document.getElementById('cbGrid').onchange = updateArrows;
document.getElementById('cbSurf').onchange = updateArrows;
document.getElementById('cbBox').onchange = (ev) => {
  boxGroup.visible = ev.target.checked;
  axesGroup.visible = ev.target.checked;
};

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'The surface in the field', n: 'A blue-gray tube S winds through a box filled with the orange field F. Arrows also lie across the tube, so you can see how F meets the surface point by point.', m: 'F', e: 'S' },
  { t: 'Switch to curl F and the normal', n: 'The orange arrows become curl F (red) together with the outward normals n dS (green). The integrand of Stokes\' theorem is curl F · n — pointing quite differently from F itself.', m: 'curl', e: 'S' },
  { t: 'Fade the surface, keep the boundary', n: 'Dim the tube and highlight only the front circular opening C with its orientation arrows. The convoluted surface is nearly impossible to parameterize.', m: 'curl', e: 'C' },
  { t: 'Stokes\' trade', n: 'Both together: the surface integral of curl F over all of S equals the line integral of F around the single small circle C — the hard object is traded for the easy one.', m: 'F', e: 'B' }
];
let step = 0;
const narr = document.getElementById('narr');
function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  setMode(s.m); setEmph(s.e);
  narr.innerHTML = `<b>${step + 1}/${STEPS.length} · ${s.t}</b><br>${s.n}`;
}
document.getElementById('btnPrev').onclick = () => { stopPlay(); goToStep(step - 1); };
document.getElementById('btnNext').onclick = () => { stopPlay(); goToStep(step + 1); };
let playId = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() { if (playId) { clearInterval(playId); playId = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); } }
btnPlay.onclick = () => {
  if (playId) { stopPlay(); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  playId = setInterval(() => goToStep(step + 1), 4200);
};

goToStep(0);
updateArrows();
updateEmphasis();
applyOpacity(1);

/* opacity tween loop (independent of the scaffold render loop) */
(function tween() {
  requestAnimationFrame(tween);
  const cur = tubeMat.opacity;
  if (Math.abs(cur - tubeTargetOpacity) > 0.004) applyOpacity(cur + (tubeTargetOpacity - cur) * 0.14);
  else if (cur !== tubeTargetOpacity) applyOpacity(tubeTargetOpacity);
})();

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.7
});

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('<i>x</i>', M(3.62, 0, -0.12), { bold: true, fontSize: '15px' });
addLabel('<i>y</i>', M(0, 3.62, -0.12), { bold: true, fontSize: '15px' });
addLabel('<i>z</i>', M(0, 0, 3.70), { bold: true, fontSize: '15px' });
addLabel('<i>S</i>', M(-2.10, 1.45, 1.00), { fontSize: '15px' });
addLabel('<i>C</i>', curve.getPointAt(1), { fontSize: '15px', offset: [-28, -18] });
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

