</div>
<div id="narr" style="font-size:11px;line-height:1.4;color:#222;background:#f2f4f8;border:1px solid #dfe3ea;border-radius:4px;padding:6px 7px;margin-top:3px"></div>

<label style="font-weight:600;margin-top:4px">Sampling</label>
<label style="flex-direction:row;align-items:center;gap:5px"><input type="checkbox" id="cbGrid" checked> arrows in space</label>
<label style="flex-direction:row;align-items:center;gap:5px"><input type="checkbox" id="cbSurf" checked> arrows on the surface</label>
<label style="flex-direction:row;align-items:center;gap:5px"><input type="checkbox" id="cbBox" checked> wireframe box &amp; ticks</label>
