  <input type="range" id="rngLen" min="0.30" max="0.80" step="0.02" value="0.46">
</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ──────────────────────────────────────────────────────────
   world box        → LineSegments(EdgesGeometry(BoxGeometry(6,6,6)))  #5B9BD5 thin
   axes x,y,z       → Line black ±3.2 + ConeGeometry head at + end (z head at top)
   ticks            → LineSegments every 0.5 unit, black, 0.09 long
   tube S           → TubeGeometry(CatmullRomCurve3, 420 seg, R=0.38, 26 radial,
                      open, DoubleSide, #6E7CA3)  — big two-lobe pretzel:
                      top band → left U-turn → bottom band → right hook →
                      front stub ending face-on at C near the centre
   inner wall       → 2nd TubeGeometry R-0.03, BackSide, #55618A
   far mouth rim    → TorusGeometry(R,0.034) at u=0 (upper-right lobe)
   boundary C rim   → TorusGeometry(R,0.046) at u=1 (faces the viewer, near centre)
   field arrows     → pooled Group(Cylinder shaft + Cone head), 4×4×4 grid over
                      [-2.5,2.5]³ plus 22 on the tube surface, #E8622A
   curl arrows      → same pool re-aimed, #C0392B, length ∝ |0.5 z|
   normals n dS     → 22 pooled arrows on the tube, #4C8C6B, length 0.36
   orientation of C → 6 tangential arrows around the C circle, gold
   labels           → x, y, z, S, C via addLabel
   Math coords (x lower-left, y lower-right, z up) map to world (mathY,mathZ,mathX).
   Screen frame (a = screen-right, b = screen-depth-in-plane, z = up) is used to
   author the tube: world = ((a-b)/√2, z, -(a+b)/√2).
──────────────────────────────────────────────────────────────────────────── */

const COL = {
  box: 0x5B9BD5, tube: 0x6E7CA3, inner: 0x55618A,
  field: 0xE8622A, curl: 0xC0392B, normal: 0x4C8C6B, gold: 0xD9A02B
};

const SQ = Math.SQRT1_2;
const M = (x, y, z) => new THREE.Vector3(y, z, x);                 // math → world
const AB = (a, b, z) => new THREE.Vector3((a - b) * SQ, z, -(a + b) * SQ); // screen-frame → world
const mathOf = (p) => ({ x: p.z, y: p.x, z: p.y });                // world → math

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.HemisphereLight(0xffffff, 0x8f95ab, 1.0));
const key = new THREE.DirectionalLight(0xffffff, 0.75);
key.position.set(-3, 6, 6); scene.add(key);
const fill = new THREE.DirectionalLight(0xffffff, 0.3);
fill.position.set(4, -2, -3); scene.add(fill);

/* ── wireframe box ──────────────────────────────────────────────────────── */
const boxGroup = new THREE.Group();
boxGroup.add(new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(6, 6, 6)),
  new THREE.LineBasicMaterial({ color: COL.box })));
scene.add(boxGroup);

/* ── axes + ticks + arrowheads ──────────────────────────────────────────── */
const axesGroup = new THREE.Group(); scene.add(axesGroup);
const blackLine = new THREE.LineBasicMaterial({ color: 0x111111 });
const blackSolid = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.6 });
const AX = [
  { dir: M(1, 0, 0), tick: new THREE.Vector3(0, 1, 0) },   // math x → world +Z (lower-left)
  { dir: M(0, 1, 0), tick: new THREE.Vector3(0, 1, 0) },   // math y → world +X (lower-right)
  { dir: M(0, 0, 1), tick: new THREE.Vector3(1, 0, 0) }    // math z → world +Y (up)
];
const tickPts = [];
for (const a of AX) {
  const L = 3.2;
  axesGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    a.dir.clone().multiplyScalar(-L), a.dir.clone().multiplyScalar(L)]), blackLine));
  for (let s = -6; s <= 6; s++) {
    if (!s) continue;
    const b = a.dir.clone().multiplyScalar(s * 0.5);
    tickPts.push(b.clone().addScaledVector(a.tick, 0.09));
    tickPts.push(b.clone().addScaledVector(a.tick, -0.09));
  }
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.26, 14), blackSolid);
  head.position.copy(a.dir).multiplyScalar(L + 0.12);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), a.dir.clone().normalize());
  axesGroup.add(head);
}
axesGroup.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(tickPts), blackLine));

/* ── tube S : big self-winding double-lobe surface ──────────────────────── */
/* analytic body in the screen frame (a = right, b = depth, z = up):
     a(t) = 2.35 sin t ,  b(t) = cos t (sin t + 0.55) ,  z(t) = 1.15 cos t
   traversed from t = 0.85 (far mouth, upper right) DOWN to t = -4.15
   → top band above the origin (behind the z-axis), wide U-turn on the left,
     bottom band below the origin (in front of the z-axis), then a hook on the
     right; hand-placed waypoints then bring the tube forward to the circle C. */
const T_A = 0.85, T_B = -4.15, R = 0.38;
function abz(t) {
  const s = Math.sin(t), c = Math.cos(t);
  return [2.35 * s, c * (s + 0.55), 1.15 * c];
}
const cPts = [];
const NA = 46;
for (let i = 0; i <= NA; i++) {
  const t = T_A + (T_B - T_A) * (i / NA);
  const p = abz(t);
  cPts.push(AB(p[0], p[1], p[2]));
}
const STUB = [
  [2.55, -0.35, -0.30],
  [2.80, -0.30, 0.20],
  [2.45, -0.55, 0.45],
  [1.70, -0.80, 0.50],
  [1.00, -1.00, 0.45],
  [0.70, -1.20, 0.48],
  [0.60, -1.42, 0.60],
  [0.58, -1.66, 0.77]      // C: last step is purely toward the viewer → face-on disc
];
for (const s of STUB) cPts.push(AB(s[0], s[1], s[2]));
const curve = new THREE.CatmullRomCurve3(cPts, false, 'centripetal', 0.5);

const tubeMat = new THREE.MeshStandardMaterial({
  color: COL.tube, roughness: 0.42, metalness: 0.08, side: THREE.DoubleSide
});
const innerMat = new THREE.MeshStandardMaterial({
  color: COL.inner, roughness: 0.8, metalness: 0.0, side: THREE.BackSide
});
const tubeMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 440, R, 26, false), tubeMat);
const innerMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 300, R - 0.03, 20, false), innerMat);
scene.add(tubeMesh, innerMesh);

registerInteractive(tubeMesh, {
  title: 'Surface S',
  tooltip: 'Surface S — too convoluted to parameterize',
  body: 'S is an oriented tube that sweeps across the box, doubles back around the left, returns underneath and hooks forward, overlapping itself in this view. Computing ∬_S (curl F)·n dS directly would need a parameterization of this whole twisted surface.'
});

function ringAt(u, thick, color) {
  const p = curve.getPointAt(u), t = curve.getTangentAt(u).normalize();
  const m = new THREE.Mesh(new THREE.TorusGeometry(R, thick, 14, 52),
    new THREE.MeshStandardMaterial({ color, roughness: 0.45, metalness: 0.1 }));
  m.position.copy(p);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), t);
  scene.add(m);
  return m;
}
const rimFar = ringAt(0, 0.034, COL.inner);
const rimC = ringAt(1, 0.048, COL.inner);
registerInteractive(rimC, {
  title: 'Boundary curve C',
  tooltip: 'Boundary circle C',
  body: "C is the oriented boundary circle of S, facing the viewer just right of the z-axis. Stokes' theorem replaces the surface integral of curl F over the whole tube by one line integral of F around this small circle."
});
registerInteractive(rimFar, {
  title: 'Far mouth of the tube',
  tooltip: 'Far open mouth (upper-right lobe)',
  body: 'The other open end of the tube, in the upper-right region. Together with C it makes up the entire free edge of the surface S.'
});

/* ── arrow pool ─────────────────────────────────────────────────────────── */
const shaftGeo = new THREE.CylinderGeometry(0.036, 0.036, 1, 10); shaftGeo.translate(0, 0.5, 0);
const headGeo = new THREE.ConeGeometry(0.112, 0.23, 14); headGeo.translate(0, 0.115, 0);
const UPY = new THREE.Vector3(0, 1, 0);
const mk = (c, e) => new THREE.MeshStandardMaterial({
  color: c, roughness: 0.55, metalness: 0.05, emissive: c, emissiveIntensity: e
});
const matField = mk(COL.field, 0.28);
const matCurl = mk(COL.curl, 0.26);
const matNorm = mk(COL.normal, 0.22);
const matGold = mk(COL.gold, 0.3);

function makeArrow(mat, parent) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(shaftGeo, mat);
  const head = new THREE.Mesh(headGeo, mat);
  g.add(shaft, head);
  g.userData = { shaft, head };
  parent.add(g);
  return g;
}
function setArrow(g, centre, dir, len, mat) {
  if (!(len > 0.02) || dir.lengthSq() < 1e-10) { g.visible = false; return; }
  const dn = dir.clone().normalize();
  g.visible = true;
  g.position.copy(centre).addScaledVector(dn, -len / 2);
  g.quaternion.setFromUnitVectors(UPY, dn);
  const hl = Math.min(0.23, len * 0.46);
  g.userData.shaft.scale.set(1, Math.max(0.01, len - hl), 1);
  g.userData.head.position.set(0, len - hl, 0);
  g.userData.head.scale.setScalar(hl / 0.23);
  if (mat) { g.userData.shaft.material = mat; g.userData.head.material = mat; }
}

/* field  F = (-1 - 0.25 z², 1.15, 0.5 + 0.45 z)  → tilts up-and-right on screen,
   steeper high in the box.    curl F = (0, -0.5 z, 0). */
function Fworld(p) {
  const m = mathOf(p);
  return M(-1 - 0.25 * m.z * m.z, 1.15, 0.5 + 0.45 * m.z);
}
function curlWorld(p) {
  const m = mathOf(p);
  return M(0, -0.5 * m.z, 0);
}

/* distance test so grid arrows never sprout out of the tube */
const probe = [];
for (let i = 0; i <= 320; i++) probe.push(curve.getPointAt(i / 320));
function nearTube(p, lim) {
  for (const q of probe) if (q.distanceToSquared(p) < lim * lim) return true;
  return false;
}

/* grid samples : 4×4×4 over [-2.5,2.5]³ in math coords */
const gridGroup = new THREE.Group(); scene.add(gridGroup);
const gridArrows = [];
const GV = [-2.5, -0.83, 0.83, 2.5];
for (const gx of GV) for (const gy of GV) for (const gz of GV) {
  const p = M(gx, gy, gz);
  gridArrows.push({ g: makeArrow(matField, gridGroup), p, hidden: nearTube(p, R + 0.42) });
}

/* samples lying on the tube surface (viewer-facing side) + outward normals */
const surfGroup = new THREE.Group(); scene.add(surfGroup);
const normGroup = new THREE.Group(); scene.add(normGroup);
const surfArrows = [], normArrows = [];
const viewDir = new THREE.Vector3(1, 1, 1).normalize();
const NS = 22;
for (let i = 0; i < NS; i++) {
  const u = 0.02 + 0.96 * (i / (NS - 1));
  const pos = curve.getPointAt(u);
  const tan = curve.getTangentAt(u).normalize();
  let n1 = new THREE.Vector3().crossVectors(tan, UPY);
  if (n1.lengthSq() < 1e-6) n1 = new THREE.Vector3().crossVectors(tan, new THREE.Vector3(1, 0, 0));
  n1.normalize();
  const n2 = new THREE.Vector3().crossVectors(tan, n1).normalize();
  let best = null, bd = -Infinity;
  for (let k = 0; k < 48; k++) {
    const th = (k / 48) * Math.PI * 2;
    const rad = n1.clone().multiplyScalar(Math.cos(th)).addScaledVector(n2, Math.sin(th));
    const dd = rad.dot(viewDir);
    if (dd > bd) { bd = dd; best = rad; }
  }
  const sp = pos.clone().addScaledVector(best, R + 0.05);
  surfArrows.push({ g: makeArrow(matField, surfGroup), p: sp, hidden: false });
  const na = makeArrow(matNorm, normGroup);
  setArrow(na, sp.clone().addScaledVector(best, 0.18), best.clone(), 0.36, matNorm);
  normArrows.push(na);
}

/* orientation arrows around C */
const orientGroup = new THREE.Group(); scene.add(orientGroup);
{
  const cEnd = curve.getPointAt(1), cTan = curve.getTangentAt(1).normalize();
  let n1 = new THREE.Vector3().crossVectors(cTan, UPY);
  if (n1.lengthSq() < 1e-6) n1 = new THREE.Vector3().crossVectors(cTan, new THREE.Vector3(1, 0, 0));
  n1.normalize();
  const n2 = new THREE.Vector3().crossVectors(cTan, n1).normalize();
  for (let i = 0; i < 6; i++) {
    const th = (i / 6) * Math.PI * 2;
    const rad = n1.clone().multiplyScalar(Math.cos(th)).addScaledVector(n2, Math.sin(th));
    const p = cEnd.clone().addScaledVector(rad, R);
    const tdir = new THREE.Vector3().crossVectors(cTan, rad).normalize();
    setArrow(makeArrow(matGold, orientGroup), p, tdir, 0.30, matGold);
  }
}
orientGroup.visible = false;

/* ── state & updates ────────────────────────────────────────────────────── */
let mode = 'F', emphasis = 'S', tubeTargetOpacity = 1;
let ARROW_LEN = 0.46;

function updateArrows() {
  for (const e of gridArrows.concat(surfArrows)) {
    if (e.hidden) { e.g.visible = false; continue; }
    if (mode === 'F') {
      setArrow(e.g, e.p, Fworld(e.p), ARROW_LEN, matField);
    } else {
      const m = mathOf(e.p);
      const mag = Math.abs(0.5 * m.z);
      if (mag < 0.09) { e.g.visible = false; continue; }
      setArrow(e.g, e.p, curlWorld(e.p),
        Math.min(0.5, Math.max(0.15, mag)) * (ARROW_LEN / 0.46), matCurl);
    }
  }
  gridGroup.visible = document.getElementById('cbGrid').checked;
  surfGroup.visible = document.getElementById('cbSurf').checked;
  normGroup.visible = (mode === 'curl') && document.getElementById('cbSurf').checked;
}

function updateEmphasis() {
  if (emphasis === 'S') {
    tubeTargetOpacity = 1.0; rimC.material.color.setHex(COL.inner);
    orientGroup.visible = false; rimC.scale.setScalar(1);
  } else if (emphasis === 'C') {
    tubeTargetOpacity = 0.15; rimC.material.color.setHex(COL.field);
    orientGroup.visible = true; rimC.scale.setScalar(1.12);
  } else {
    tubeTargetOpacity = 0.55; rimC.material.color.setHex(COL.field);
    orientGroup.visible = true; rimC.scale.setScalar(1.12);
  }
}
function applyOpacity(v) {
  for (const m of [tubeMat, innerMat]) {
    m.opacity = v; m.transparent = v < 0.995; m.depthWrite = v > 0.995; m.needsUpdate = true;
  }
}

/* buttons */
const bF = document.getElementById('btnModeF'), bC = document.getElementById('btnModeCurl');
const eS = document.getElementById('btnEmS'), eC = document.getElementById('btnEmC'), eB = document.getElementById('btnEmB');
const modeNote = document.getElementById('modeNote');
function syncUI() {
  bF.classList.toggle('active', mode === 'F');
  bC.classList.toggle('active', mode === 'curl');
  eS.classList.toggle('active', emphasis === 'S');
  eC.classList.toggle('active', emphasis === 'C');
  eB.classList.toggle('active', emphasis === 'B');
  modeNote.innerHTML = mode === 'F'
    ? '<b>F</b> = (&minus;1 &minus; 0.25<i>z</i>², 1.15, 0.5 + 0.45<i>z</i>): every arrow is drawn the same length and tilts up and to the right, more steeply high in the box.'
    : '<b>curl F</b> = (0, &minus;0.5<i>z</i>, 0) in red — it vanishes on <i>z</i> = 0 and grows away from it. Green arrows are the outward unit normals <b>n</b> on <i>S</i>; the integrand is curl <b>F</b> · <b>n</b>.';
}
const setMode = m => { mode = m; updateArrows(); syncUI(); };
const setEmph = e => { emphasis = e; updateEmphasis(); syncUI(); };
bF.onclick = () => setMode('F');
bC.onclick = () => setMode('curl');
eS.onclick = () => setEmph('S');
eC.onclick = () => setEmph('C');
eB.onclick = () => setEmph('B');
document.getElementById('cbGrid').onchange = updateArrows;
document.getElementById('cbSurf').onchange = updateArrows;
document.getElementById('cbBox').onchange = ev => {
  boxGroup.visible = ev.target.checked; axesGroup.visible = ev.target.checked;
};
document.getElementById('rngLen').oninput = ev => {
  ARROW_LEN = parseFloat(ev.target.value); updateArrows();
};

/* ── demo steps ─────────────────────────────────────────────────────────── */
const STEPS = [
  { t: 'The surface in the field', n: 'A blue-gray tube <i>S</i> winds right across the box, doubles back around the left and hooks forward, all inside the orange field <b>F</b>. Arrows also lie directly on the tube, so you can see how <b>F</b> meets the surface point by point.', m: 'F', e: 'S' },
  { t: 'Switch to curl F and the normal', n: 'The arrows become curl <b>F</b> (red) together with the outward normals <b>n</b> <i>dS</i> (green). The integrand of Stokes\' theorem is curl <b>F</b> · <b>n</b> — pointing quite differently from <b>F</b> itself.', m: 'curl', e: 'S' },
  { t: 'Fade the surface, keep the boundary', n: 'Dim the tube and highlight only the front circular opening <i>C</i> with its orientation arrows. The convoluted, self-overlapping surface is nearly impossible to parameterize; the circle is trivial.', m: 'curl', e: 'C' },
  { t: 'Stokes\' trade', n: 'Both together: the surface integral of curl <b>F</b> over all of <i>S</i> equals the line integral of <b>F</b> around the single small circle <i>C</i> — the hard object is traded for the easy one.', m: 'F', e: 'B' }
];
let step = 0;
const narr = document.getElementById('narr');
function goToStep(i) {
  step = (i + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  setMode(s.m); setEmph(s.e);
  narr.innerHTML = `<b>${step + 1}/${STEPS.length} · ${s.t}</b><br>${s.n}`;
}
document.getElementById('btnPrev').onclick = () => { stopPlay(); goToStep(step - 1); };
document.getElementById('btnNext').onclick = () => { stopPlay(); goToStep(step + 1); };
let playId = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() { if (playId) { clearInterval(playId); playId = null; btnPlay.textContent = '▶ Play'; btnPlay.classList.remove('active'); } }
btnPlay.onclick = () => {
  if (playId) { stopPlay(); return; }
  btnPlay.textContent = '❚❚ Pause'; btnPlay.classList.add('active');
  playId = setInterval(() => goToStep(step + 1), 4500);
};

goToStep(0);
updateArrows();
updateEmphasis();
applyOpacity(1);

(function tween() {
  requestAnimationFrame(tween);
  const cur = tubeMat.opacity;
  if (Math.abs(cur - tubeTargetOpacity) > 0.004) applyOpacity(cur + (tubeTargetOpacity - cur) * 0.14);
  else if (cur !== tubeTargetOpacity) applyOpacity(tubeTargetOpacity);
})();

/* ── camera (after all geometry) ────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  rollDeg: 0,
  heightFraction: 0.74
});

/* ── labels ─────────────────────────────────────────────────────────────── */
addLabel('<i>x</i>', M(3.5, 0, -0.08), { bold: true, fontSize: '15px', offset: [-10, 10] });
addLabel('<i>y</i>', M(0, 3.5, -0.08), { bold: true, fontSize: '15px', offset: [10, 10] });
addLabel('<i>z</i>', M(0, 0, 3.5), { bold: true, fontSize: '15px', offset: [-12, -8] });
addLabel('<i>S</i>', AB(2.15, 0.90, 1.00), { fontSize: '16px', offset: [6, -4] });
